<?php declare(strict_types=1); namespace App\Controller; use Cake\Http\Response; class ParqueaderosController extends AppController { public function index():?Response {$this->set('items',$this->Parqueaderos->find()->all());return null;} public function add():?Response {$item=$this->Parqueaderos->newEmptyEntity();if($this->request->is('post')){$item=$this->Parqueaderos->patchEntity($item,$this->request->getData());if($this->Parqueaderos->save($item))return $this->redirect(['action'=>'index']);}$this->set(compact('item'));return null;} public function edit(int $id):?Response {$item=$this->Parqueaderos->get($id);if($this->request->is(['post','put','patch'])){$item=$this->Parqueaderos->patchEntity($item,$this->request->getData());if($this->Parqueaderos->save($item))return $this->redirect(['action'=>'index']);}$this->set(compact('item'));return null;} }
